fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    for i in 0..n {
        // place element from the end of `a` into the next slot of `result`
        result.push(a[n - 1 - i]);
    }
    result
}

